//! `alias_keys` must reproduce, byte for byte, the Tier A / Tier B keys the
//! JavaScript implementation computed (`computeTierAAliasKey` /
//! `computeTierBAliasKey` on the WHATWG `URL` of Node), which is what the
//! groupings stored in existing archives (`content_items.alias_of_id`) were
//! built from. `fixtures/alias-keys-golden.json` was generated by that
//! implementation. Each case stores its input only as UTF-8 hex, not as a
//! JSON string, so inputs `serde_json` cannot hold stay representable.

use nitpicker_url_key::alias_keys;
use serde_json::Value;

fn decode_hex(hex: &str) -> Vec<u8> {
	assert!(hex.len().is_multiple_of(2), "odd-length hex string");
	(0..hex.len())
		.step_by(2)
		.map(|i| u8::from_str_radix(&hex[i..i + 2], 16).expect("valid hex digit pair"))
		.collect()
}

#[test]
fn matches_every_golden_key_from_the_js_implementation() {
	let golden: Value = serde_json::from_str(include_str!("fixtures/alias-keys-golden.json"))
		.expect("golden fixture is valid JSON");
	let cases = golden.as_array().expect("golden fixture is an array");
	assert!(!cases.is_empty(), "golden fixture has no cases");
	for case in cases {
		let name = case["name"].as_str().expect("case has a name");
		let input = String::from_utf8(decode_hex(
			case["utf8Hex"].as_str().expect("case has utf8Hex"),
		))
		.expect("the inputs are valid UTF-8");
		let expected_a = case["tierA"].as_str();
		let expected_b = case["tierB"].as_str();
		let actual = alias_keys(&input);
		assert_eq!(
			actual.as_ref().map(|keys| keys.tier_a.as_str()),
			expected_a,
			"tier A of {name}"
		);
		assert_eq!(
			actual.as_ref().map(|keys| keys.tier_b.as_str()),
			expected_b,
			"tier B of {name}"
		);
	}
}
